// M15 Phase 1B — compile the tree-sitter parser.c + scanner.c via cc.
//
// `parser.c` is generated by `tree-sitter generate` from `grammar.js`
// (re-run by hand when the grammar changes). `scanner.c` is the
// hand-rolled C external scanner that handles `.grx`'s state-aware
// raw_body lexing.

fn main() {
    let src_dir = std::path::PathBuf::from("src");

    let mut build = cc::Build::new();
    build
        .include(&src_dir)
        .file(src_dir.join("parser.c"))
        .file(src_dir.join("scanner.c"));

    // Tree-sitter's generated parser.c uses comparisons that fire
    // -Wunused-but-set-parameter and similar warnings on some
    // toolchains. Quiet them so a build doesn't fail under -Werror
    // configurations.
    build.flag_if_supported("-Wno-unused-parameter");
    build.flag_if_supported("-Wno-unused-but-set-variable");

    build.compile("tree-sitter-grx");

    println!("cargo:rerun-if-changed=src/parser.c");
    println!("cargo:rerun-if-changed=src/scanner.c");
    println!("cargo:rerun-if-changed=grammar.js");
}
